// ============================================================
// Altamira Capital - Daily Portfolio Snapshot Calculator
// ============================================================
// Inputs:
//   items[0] = E-Trade portfolio response
//   items[1] = E-Trade balance response
//   items[2] = FMP VIX & SPY response
// ============================================================

const portfolioData = $input.all()[0].json;
const balanceData = $input.all()[1].json;
const marketData = $input.all()[2].json;

// -----------------------------------------------------------
// Parse E-Trade Portfolio positions
// -----------------------------------------------------------
const positions = portfolioData?.PortfolioResponse?.AccountPortfolio?.[0]?.Position || [];

let netDelta = 0;
let dailyTheta = 0;
let openCSPCount = 0;
let openEquityCount = 0;
let totalPositionValue = 0;

for (const pos of positions) {
  const quantity = pos.quantity || 0;
  const marketValue = pos.marketValue || 0;
  totalPositionValue += marketValue;

  // Check if this is an options position
  if (pos.Product?.securityType === 'OPTN' || pos.Product?.securityType === 'OPT') {
    // Options position - extract Greeks
    const delta = pos.Complete?.delta || pos.delta || 0;
    const theta = pos.Complete?.theta || pos.theta || 0;

    netDelta += delta * quantity * 100; // Delta per contract * contracts * multiplier
    dailyTheta += theta * quantity * 100;

    // Identify CSPs: short puts (negative quantity, put type)
    const callPut = pos.Product?.callPut || pos.Product?.optionType || '';
    if (quantity < 0 && (callPut === 'PUT' || callPut === 'P')) {
      openCSPCount += Math.abs(quantity);
    }
  } else {
    // Equity position
    const delta = 1.0; // Equity delta is 1.0 per share
    netDelta += delta * quantity;
    openEquityCount += 1;
  }
}

// -----------------------------------------------------------
// Parse E-Trade Balance
// -----------------------------------------------------------
const balanceComputed = balanceData?.BalanceResponse?.Computed || balanceData?.BalanceResponse || {};
const cashAvailable = balanceComputed?.cashAvailableForInvestment
  || balanceComputed?.cashBalance
  || balanceComputed?.Cash?.moneyMktBalance
  || 0;
const accountValue = balanceComputed?.RealTimeValues?.totalAccountValue
  || balanceComputed?.accountBalance
  || 0;
const buyingPower = balanceComputed?.buyingPower || 0;

const portfolioValue = accountValue || (cashAvailable + totalPositionValue);
const cashPercent = portfolioValue > 0 ? ((cashAvailable / portfolioValue) * 100).toFixed(2) : 0;

// -----------------------------------------------------------
// Parse FMP Market Data (VIX and SPY)
// -----------------------------------------------------------
let vixClose = 0;
let spyClose = 0;

const fmpQuotes = Array.isArray(marketData) ? marketData : (marketData?.json ? (Array.isArray(marketData.json) ? marketData.json : [marketData.json]) : []);

for (const quote of fmpQuotes) {
  const symbol = (quote.symbol || '').toUpperCase();
  if (symbol === '^VIX' || symbol === 'VIX') {
    vixClose = quote.price || quote.previousClose || 0;
  }
  if (symbol === 'SPY') {
    spyClose = quote.price || quote.previousClose || 0;
  }
}

// -----------------------------------------------------------
// Calculate daily P&L (requires previous day's value)
// In production, read the last row from Google Sheets
// For now, we set it as N/A until historical data exists
// -----------------------------------------------------------
const today = new Date();
const dateStr = today.toISOString().split('T')[0]; // YYYY-MM-DD

const dailyPnL = 0; // Placeholder - will be calculated from sheet history
const dailyPnLPercent = 0;
const cumulativePnL = portfolioValue - 100000; // Starting capital = $100K
const cumulativePnLPercent = ((portfolioValue - 100000) / 100000 * 100).toFixed(2);

// -----------------------------------------------------------
// Build output row for Google Sheets
// -----------------------------------------------------------
const output = {
  date: dateStr,
  portfolioValue: Math.round(portfolioValue * 100) / 100,
  dailyPnL: Math.round(dailyPnL * 100) / 100,
  dailyPnLPercent: dailyPnLPercent,
  cumulativePnL: Math.round(cumulativePnL * 100) / 100,
  cumulativePnLPercent: parseFloat(cumulativePnLPercent),
  netDelta: Math.round(netDelta * 100) / 100,
  dailyTheta: Math.round(dailyTheta * 100) / 100,
  openCSPCount: openCSPCount,
  openEquityCount: openEquityCount,
  cashPercent: parseFloat(cashPercent),
  cashAvailable: Math.round(cashAvailable * 100) / 100,
  buyingPower: Math.round(buyingPower * 100) / 100,
  vixClose: Math.round(vixClose * 100) / 100,
  spyClose: Math.round(spyClose * 100) / 100,
  notes: ''
};

// -----------------------------------------------------------
// Build Telegram message
// -----------------------------------------------------------
const deltaEmoji = netDelta > 50 ? '\u26a0\ufe0f HIGH' : netDelta < -30 ? '\u26a0\ufe0f LOW' : '\u2705 OK';
const cashEmoji = parseFloat(cashPercent) < 15 ? '\u26a0\ufe0f BELOW MIN' : '\u2705 OK';
const thetaEmoji = dailyTheta > 0 ? '\u2705 Positive' : '\u26a0\ufe0f Negative';

const telegramMessage = `ALTAMIRA CAPITAL - Daily Portfolio Snapshot\n` +
  `Date: ${dateStr}\n` +
  `-------------------------------------------\n` +
  `Portfolio Value: $${portfolioValue.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}\n` +
  `Cumulative P&L: $${cumulativePnL.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} (${cumulativePnLPercent}%)\n` +
  `-------------------------------------------\n` +
  `Net Delta: ${netDelta.toFixed(2)} ${deltaEmoji}\n` +
  `Daily Theta: $${dailyTheta.toFixed(2)} ${thetaEmoji}\n` +
  `-------------------------------------------\n` +
  `Open CSPs: ${openCSPCount}\n` +
  `Open Equity Positions: ${openEquityCount}\n` +
  `Cash: $${cashAvailable.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} (${cashPercent}%) ${cashEmoji}\n` +
  `Buying Power: $${buyingPower.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}\n` +
  `-------------------------------------------\n` +
  `VIX: ${vixClose}\n` +
  `SPY: $${spyClose}\n` +
  `-------------------------------------------\n`;

output.telegramMessage = telegramMessage;

// -----------------------------------------------------------
// Build Position History rows (one per position for optimization)
// -----------------------------------------------------------
const positionHistoryRows = [];
for (const pos of positions) {
  const quantity = pos.quantity || 0;
  const marketValue = pos.marketValue || 0;
  const weightPct = portfolioValue > 0 ? (marketValue / portfolioValue) * 100 : 0;
  const isOption = pos.Product?.securityType === 'OPTN' || pos.Product?.securityType === 'OPT';
  const assetType = isOption ? 'OPT' : 'EQ';
  const symbol = pos.symbol || pos.SymbolDescription || pos.Product?.symbol || '';
  let delta = 0, theta = 0, strike = '', expiration = '', callPut = '';
  if (isOption) {
    delta = pos.Complete?.delta ?? pos.delta ?? 0;
    theta = pos.Complete?.theta ?? pos.theta ?? 0;
    strike = pos.strikePrice ?? pos.Product?.strikePrice ?? '';
    const exp = pos.expiryDate ?? pos.Product?.expiryDate;
    expiration = exp ? (typeof exp === 'number' ? new Date(exp).toISOString().split('T')[0] : String(exp).substring(0, 10)) : '';
    const cp = pos.Product?.callPut || pos.Product?.optionType || '';
    callPut = (cp === 'PUT' || cp === 'P') ? 'P' : (cp === 'CALL' || cp === 'C') ? 'C' : '';
  } else {
    delta = 1.0;
  }
  positionHistoryRows.push({
    date: dateStr,
    symbol: symbol,
    assetType: assetType,
    quantity: quantity,
    marketValue: Math.round(marketValue * 100) / 100,
    weightPct: Math.round(weightPct * 100) / 100,
    sector: '',
    delta: Math.round(delta * 100) / 100,
    theta: Math.round(theta * 100) / 100,
    strike: strike !== '' ? (typeof strike === 'number' ? Math.round(strike * 100) / 100 : strike) : '',
    expiration: expiration,
    callPut: callPut
  });
}
const summaryItem = { json: output };
const positionItems = positionHistoryRows.map(r => ({ json: r }));
return [summaryItem, ...positionItems];
